{
  "states": ["STABLE", "CHANGING", "UNSTABLE"],
  "transitions": [
    {
      "from": "STABLE",
      "event": "rcv Change R",
      "action": "calc new value, snd Confirm L",
      "to": "STABLE"
    },
    {
      "from": "STABLE",
      "event": "app/protocol evt",
      "action": "snd Change L",
      "to": "CHANGING"
    },
    {
      "from": "CHANGING",
      "event": "rcv Confirm R",
      "action": "if valid value set F.value, set F.state := STABLE",
      "to": "STABLE"
    },
    {
      "from": "CHANGING",
      "event": "pref list changes",
      "action": "transition to UNSTABLE",
      "to": "UNSTABLE"
    },
    {
      "from": "UNSTABLE",
      "event": "snd Change L",
      "action": "transition back to CHANGING",
      "to": "CHANGING"
    }
  ]
}

{
  "states": ["CLOSED", "LISTEN", "REQUEST", "RESPOND", "PARTOPEN", "OPEN"],
  "transitions": [
    {
      "from": "REQUEST",
      "event": "receives DCCP-Response",
      "action": "moves to PARTOPEN",
      "to": "PARTOPEN"
    },
    {
      "from": "PARTOPEN",
      "event": "receives valid packet other than DCCP-Response, DCCP-Reset, or DCCP-Sync",
      "action": "moves to OPEN",
      "to": "OPEN"
    },
    {
      "from": "LISTEN",
      "event": "receives DCCP-Request",
      "action": "moves to RESPOND",
      "to": "RESPOND"
    },
    {
      "from": "RESPOND",
      "event": "receives valid DCCP-Ack",
      "action": "moves to OPEN",
      "to": "OPEN"
    },
    {
      "from": "RESPOND",
      "event": "timeout of 4MSL",
      "action": "moves to CLOSED",
      "to": "CLOSED"
    },
    {
      "from": "PARTOPEN",
      "event": "timeout of 4MSL",
      "action": "resets connection with Reset Code 2",
      "to": "CLOSED"
    },
    {
      "from": "PARTOPEN",
      "event": "sends DCCP-Ack or DCCP-DataAck",
      "action": "moves to OPEN",
      "to": "OPEN"
    }
  ]
}

{
  "states": ["OPEN"],
  "transitions": [
    {
      "from": "OPEN",
      "event": "",
      "action": "send DCCP-Data and DCCP-DataAck packets, congestion-controlled by CCID for A-to-B half-connection",
      "to": "OPEN"
    },
    {
      "from": "OPEN",
      "event": "",
      "action": "send DCCP-Ack packets controlled by B-to-A CCID",
      "to": "OPEN"
    },
    {
      "from": "OPEN",
      "event": "receiving valid DCCP-Sync packet",
      "action": "immediately send DCCP-SyncAck with Acknowledgement Number equal to Sequence Number of DCCP-Sync",
      "to": "OPEN"
    }
  ]
}

